(function(){var root=document.querySelector('.department-multi-dropdown');if(!root)return;var menu=root.querySelector('.department-multi-menu'),tags=root.querySelector('[data-department-tags]'),placeholder=root.querySelector('[data-department-placeholder]'),boxes=root.querySelectorAll('input[type="checkbox"]'),clear=root.querySelector('.department-multi-clear');function refresh(){tags.innerHTML='';var count=0;boxes.forEach(function(box){if(!box.checked)return;count++;var tag=document.createElement('span');tag.className='department-tag';tag.setAttribute('data-tag-id',box.value);tag.appendChild(document.createTextNode(box.getAttribute('data-name')||''));var remove=document.createElement('span');remove.className='department-tag-remove';remove.setAttribute('data-remove-id',box.value);remove.textContent='×';tag.appendChild(remove);tags.appendChild(tag);});placeholder.style.display=count?'none':'inline-block';}menu.addEventListener('click',function(event){event.stopPropagation();var group=event.target.closest('[data-department-group]');if(group&&!event.target.closest('input')){root.querySelectorAll('[data-department-group]').forEach(function(item){item.classList.toggle('active',item===group);});root.querySelectorAll('[data-department-panel]').forEach(function(panel){panel.classList.toggle('active',panel.getAttribute('data-department-panel')===group.getAttribute('data-department-group'));});}});root.addEventListener('click',function(event){var remove=event.target.closest('[data-remove-id]');if(!remove)return;event.preventDefault();event.stopPropagation();var box=root.querySelector('input[value="'+CSS.escape(remove.getAttribute('data-remove-id'))+'"]');if(box)box.checked=false;refresh();});boxes.forEach(function(box){box.addEventListener('change',refresh);});clear.addEventListener('click',function(){boxes.forEach(function(box){box.checked=false;});refresh();});refresh();})();
(function(){window.syncOperationReportRowspans=function(table,collapsed){if(!table)return;table.querySelectorAll('[data-detail-rowspan]').forEach(function(cell){cell.rowSpan=collapsed?1:Number(cell.getAttribute('data-detail-rowspan')||1);});};window.reorderOperationReportColumns=function(table,expanded){if(!table)return;var summaryHeader=Array.prototype.find.call(table.querySelectorAll('thead th'),function(cell){return cell.textContent.trim()==='首单总营业额($)';});if(summaryHeader){summaryHeader.setAttribute('data-report-column','first-total-summary');var footer=table.querySelector('tfoot tr');if(footer&&footer.cells[summaryHeader.cellIndex-1])footer.cells[summaryHeader.cellIndex-1].setAttribute('data-report-column','first-total-summary');}table.querySelectorAll('tr').forEach(function(row){var shop=row.querySelector('[data-report-column="shop"]'),hire=row.querySelector('[data-report-column="hire-days"]'),ad=row.querySelector('[data-report-column="ad-spend"]'),revenue=row.querySelector('[data-report-column="first-total-summary"]');if(expanded){if(shop&&hire)row.insertBefore(hire,shop);}else{if(shop&&hire)row.insertBefore(hire,shop.nextSibling);}if(ad&&revenue)row.insertBefore(ad,revenue);});};document.querySelectorAll('.report-table').forEach(function(table){window.reorderOperationReportColumns(table,!table.classList.contains('details-collapsed'));});document.querySelectorAll('.detail-column-toggle').forEach(function(button){button.addEventListener('click',function(){var table=document.getElementById(button.getAttribute('data-table'));if(!table)return;var collapsed=table.classList.toggle('details-collapsed');window.reorderOperationReportColumns(table,!collapsed);window.syncOperationReportRowspans(table,collapsed);button.querySelector('span').textContent=collapsed?'显示明细列':'隐藏明细列';});});})();
(function($){var modal=$('#assistantReportEnlargeModal'),body=document.getElementById('assistantReportEnlargeBody'),note=document.getElementById('assistantReportScaleNote'),mode='core';function fit(){var stage=body&&body.querySelector('.report-screenshot-stage');if(!stage)return;stage.style.transform='none';stage.style.left='0';stage.style.top='0';var width=stage.scrollWidth,height=stage.scrollHeight,availableWidth=Math.max(1,body.clientWidth-12),availableHeight=Math.max(1,body.clientHeight-12),scale=Math.min(1,availableWidth/width,availableHeight/height);stage.style.transform='scale('+scale+')';stage.style.left=Math.max(6,(body.clientWidth-width*scale)/2)+'px';stage.style.top=Math.max(6,(body.clientHeight-height*scale)/2)+'px';if(note)note.textContent=(mode==='core'?'清晰核心数据':'全部字段')+' · 全部行 · 缩放 '+Math.round(scale*100)+'%';}function applyMode(nextMode){mode=nextMode;var table=body&&body.querySelector('.report-table');if(!table)return;table.classList.toggle('details-collapsed',mode==='core');window.reorderOperationReportColumns(table,mode!=='core');window.syncOperationReportRowspans(table,mode==='core');modal.find('[data-report-shot-mode]').removeClass('active').filter('[data-report-shot-mode="'+mode+'"]').addClass('active');window.requestAnimationFrame(fit);}modal.on('show.bs.modal',function(){var source=document.getElementById('assistant-report-table');if(!source||!body)return;var stage=document.createElement('div'),table=source.cloneNode(true);stage.className='report-screenshot-stage';table.removeAttribute('id');table.classList.add('details-collapsed');window.reorderOperationReportColumns(table,false);window.syncOperationReportRowspans(table,true);stage.appendChild(table);body.innerHTML='';body.appendChild(stage);mode='core';modal.find('[data-report-shot-mode]').removeClass('active').filter('[data-report-shot-mode="core"]').addClass('active');if(note)note.textContent='正在适配全部数据…';});modal.on('shown.bs.modal',function(){window.requestAnimationFrame(fit);});modal.on('hidden.bs.modal',function(){if(body)body.innerHTML='';});modal.on('click','[data-report-shot-mode]',function(){applyMode($(this).attr('data-report-shot-mode'));});$(window).on('resize',function(){if(modal.hasClass('in'))fit();});})(jQuery);
(function($){
    var endpoint=@json($orderDetailsUrl), activeQuery=null;
    var typeLabels={first_subscription:'首单订阅',first_normal:'首单普通',first_total:'首单合计',renewal:'续费单',total:'全部订单'};
    function esc(value){return $('<div>').text(value==null?'':String(value)).html();}
    function money(value){return '$'+Number(value||0).toFixed(2);}
    function num(value){return Number(value||0).toLocaleString(undefined,{maximumFractionDigits:2});}
    function render(data,type){
        var s=data.summary,html='<div class="detail-formula" style="margin-bottom:12px"><strong>'+esc(typeLabels[type])+'</strong> · '+esc(s.date)+' · '+esc(s.shop_domain)+' · '+esc(s.media_source)+'</div>';
        var domains=s.shop_domains||[];html+='<div class="detail-domain-panel"><span class="detail-domain-title"><i class="fa fa-globe"></i> 运营对应店铺域名</span><div class="detail-domain-list">'+(domains.length?domains.map(function(domain){return '<span class="detail-domain-badge">'+esc(domain)+'</span>';}).join(''):'<span class="text-muted">暂无店铺域名</span>')+'</div></div>';
        html+='<div class="detail-summary"><div><span>订单数量</span><strong>'+s.order_count+' 单</strong></div><div><span>营业额</span><strong>'+money(s.revenue)+'</strong></div><div><span>采购费</span><strong>'+money(s.purchase_cost)+'</strong></div><div><span>运费</span><strong>'+money(s.shipping_cost)+'</strong></div><div><span>交易退货费</span><strong>'+money(s.return_fee)+'</strong></div></div>';
        if(s.media_breakdown&&s.media_breakdown.length){html+='<div class="detail-media-breakdown">';s.media_breakdown.forEach(function(media){html+='<div class="detail-media-item"><b>'+esc(media.media_source)+'</b><span>'+media.order_count+' 单</span><span>'+money(media.revenue)+'</span></div>';});html+='</div>';}
        data.orders.forEach(function(order){
            html+='<div class="detail-order"><div class="detail-order-head"><div><strong>订单 '+esc(order.order_number)+'</strong> <span class="label label-info">'+esc(order.subscription_type)+'</span><span class="detail-order-media">'+esc(order.media_source)+'</span><span class="detail-order-domain"><i class="fa fa-globe"></i> '+esc(order.shop_domain)+'</span><div class="detail-formula">订单ID：'+esc(order.shopify_order_id)+' · 系统ID：'+esc(order.id)+' · 店铺：'+esc(order.shop_domain)+' · 下单时间（UTC-4）：'+esc(order.ordered_at)+'</div></div><div class="detail-order-metrics"><span>营业额 <b>'+money(order.revenue)+'</b></span><span>采购费 <b>'+money(order.purchase_cost)+'</b></span><span>重量 <b>'+num(order.total_weight_gram)+'g</b></span><span>运费 <b>'+money(order.shipping_cost)+'</b></span><span>退货费 <b>'+money(order.return_fee)+'</b></span></div></div>';
            html+='<div class="table-responsive"><table class="table detail-item-table"><thead><tr><th>商品</th><th>SKU</th><th>数量</th><th>采购价(CNY)</th><th>采购费($)</th><th>单件重量</th><th>商品总重量</th></tr></thead><tbody>';
            order.items.forEach(function(item){var image=item.image_url?'<img src="'+esc(item.image_url)+'" alt="">':'';html+='<tr><td><div class="detail-product">'+image+'<span>'+esc(item.product_name)+'</span></div></td><td>'+esc(item.sku)+'</td><td>'+num(item.quantity)+'</td><td>'+(item.guide_cost_cny==null?'<span class="text-danger">缺失</span>':'¥'+num(item.guide_cost_cny))+'</td><td>'+money(item.purchase_cost_usd)+'</td><td>'+(item.unit_weight_gram==null?'<span class="text-danger">缺失</span>':num(item.unit_weight_gram)+'g')+'</td><td>'+num(item.total_weight_gram)+'g</td></tr>';});
            html+='</tbody></table></div><div class="detail-formula" style="padding:0 14px 12px">采购费＝采购价 × 数量 ÷ 6.5；运费＝（订单商品总重量 ÷ 1000 × 80 ＋ 20）÷ 6.5；首单交易退货费＝营业额 × 12%</div></div>';
        });
        var p=data.pagination;if(p&&p.total>0){html+='<div class="detail-pagination"><span>显示第 '+p.from+'-'+p.to+' 条，共 '+p.total+' 个订单</span><div class="detail-pagination-buttons"><button class="btn btn-default btn-sm detail-page-btn" data-page="'+(p.current_page-1)+'" '+(p.current_page<=1?'disabled':'')+'><i class="fa fa-angle-left"></i></button>';var start=Math.max(1,p.current_page-2),end=Math.min(p.last_page,start+4);start=Math.max(1,end-4);for(var page=start;page<=end;page++)html+='<button class="btn btn-default btn-sm detail-page-btn '+(page===p.current_page?'active':'')+'" data-page="'+page+'">'+page+'</button>';html+='<button class="btn btn-default btn-sm detail-page-btn" data-page="'+(p.current_page+1)+'" '+(p.current_page>=p.last_page?'disabled':'')+'><i class="fa fa-angle-right"></i></button></div></div>';}
        return html;
    }
    function load(page){var body=$('#assistantOrderDetailBody');body.html('<div class="text-center text-muted" style="padding:50px"><i class="fa fa-spinner fa-spin"></i> 正在加载订单明细...</div>');$.get(endpoint,$.extend({},activeQuery,{page:page,per_page:10})).done(function(data){body.html(render(data,activeQuery.type));}).fail(function(xhr){body.html('<div class="alert alert-danger">订单明细加载失败：'+esc((xhr.responseJSON&&xhr.responseJSON.message)||'请稍后重试')+'</div>');});}
    $(document).on('click','.order-count-link',function(){var b=$(this);activeQuery={date_from:b.attr('data-date-from'),date_to:b.attr('data-date-to'),timezone:@json($timezone),operator_user_id:b.data('operator'),type:b.data('type')};$('#assistantOrderDetailModal').modal('show');load(1);});
    $(document).on('click','.detail-page-btn:not([disabled])',function(){load(Number($(this).data('page')));});
})(jQuery);
